//! 📨️ Original command custody and a genuine read qualification authorize one exact registered child command.
use super::ChildVectorReadStamp;
use crate::child_view::editor::{registration::ChildEditorRegistration,read::ChildEditorRead,source::{ChildEditorCapability,ChildEditorRequest,ChildEditorSourceCursor,ChildEditorSourceStep,ChildEditorStamp}};
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,retained_clone::{RetainedCloneRef,RetainedCloneBinding,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits},retirement::{RetireOwned,RetirementCursor,RetirementStep}};
#[derive(Clone,Copy,PartialEq,Eq)]enum Phase{Parent,Command,Qualify,Closed}
pub struct OriginalChildEditorCommandCursor{issued:Option<ChildEditorStamp>,command_identity:Option<(u64,usize,usize,usize)>,parent:Option<RetainedCloneBinding>,command:Option<RetainedCloneBinding>,read:Option<ChildVectorReadStamp>,capability:Option<&'static ChildEditorCapability>,cursor:ChildEditorSourceCursor,phase:Phase,closing:bool}
pub struct OriginalChildEditorCommandAdvance{pub progress:RetainedCloneProgress,pub stamp:Option<ChildEditorStamp>}
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl OriginalChildEditorCommandCursor{
 const HEADER:usize=2*std::mem::size_of::<Self>();
 pub fn birth_demand()->RetirementDemand{RetirementDemand{copy_bytes:Self::HEADER,depth:1,..Default::default()}}
 pub fn admit(g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{let d=Self::birth_demand();if !retained_clone_grant_admits(g,d){return Err(refusal("Original child command birth is unfunded"))}Ok((Self{issued:None,command_identity:None,parent:None,command:None,read:None,capability:None,cursor:ChildEditorSourceCursor::new(),phase:Phase::Parent,closing:false},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 fn nested(d:RetirementDemand)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:d.copy_bytes.checked_add(Self::HEADER).ok_or_else(||refusal("Original child command quote overflow"))?,depth:d.depth.checked_add(1).ok_or_else(||refusal("Original child command depth overflow"))?,..d})}
 fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.saturating_sub(Self::HEADER),maximum_depth:g.maximum_depth.saturating_sub(1),..g}}
 fn paid(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes+=Self::HEADER;p}
 fn failure(error:ValueError)->ValueError{let p=Self::paid(error.retained_progress());error.with_retained_progress(p)}
 pub fn next_demand(&self)->Result<RetirementDemand,ValueError>{Self::nested(if self.phase==Phase::Qualify{self.cursor.next_demand()}else{RetirementDemand{copy_bytes:RetainedCloneBinding::alias_copy_bytes(),depth:1,..Default::default()}})}
 fn verify<P:Sync,C:Sync,S>(&self,parent:RetainedCloneRef<'_,P>,command:RetainedCloneRef<'_,C>,qualified:&ChildVectorReadStamp,read:&ChildEditorRead<'_,S>,capability:&'static ChildEditorCapability)->Result<(),ValueError>{
  if self.closing||self.phase==Phase::Closed{return Err(refusal("Original child command is closing"))}
  if let Some(binding)=self.parent.as_ref(){if !parent.matches_binding(binding){return Err(refusal("Original child command parent changed"))}}
  if self.command_identity.is_some_and(|identity|identity!=command.reference_identity()){return Err(refusal("Original child command source changed"))}
  if let Some(binding)=self.command.as_ref(){if !command.matches_binding(binding){return Err(refusal("Original child command source changed"))}}
  let current=read.member_metadata();
  if qualified.original!=parent.reference_identity()||qualified.parent!=current.parent_identity||qualified.child!=current.child_identity||qualified.parent_revision!=*current.parent_revision||qualified.child_revision!=*current.child_revision{return Err(refusal("Original child command read qualification changed"))}
  if self.read.is_some_and(|expected|expected!=*qualified)||self.capability.is_some_and(|expected|!std::ptr::eq(expected,capability)){return Err(refusal("Original child command registered capability changed"))}Ok(())
 }
 fn advance<P:Sync,C:Sync,S>(&mut self,parent:RetainedCloneRef<'_,P>,command:RetainedCloneRef<'_,C>,qualified:&ChildVectorReadStamp,read:&ChildEditorRead<'_,S>,registration:&'static ChildEditorRegistration<S>,g:RetainedCloneGrant)->Result<OriginalChildEditorCommandAdvance,ValueError>{
  let d=self.next_demand()?;if !retained_clone_grant_admits(g,d){return Ok(OriginalChildEditorCommandAdvance{progress:Default::default(),stamp:None})}
  self.verify(parent,command,qualified,read,&registration.identity).map_err(Self::failure)?;let child=Self::child(g);
  match self.phase{
   Phase::Parent=>{let p=parent.bind(&mut self.parent,child).map_err(Self::failure)?.unwrap_or_default();self.command_identity=Some(command.reference_identity());self.read=Some(*qualified);self.capability=Some(&registration.identity);self.phase=Phase::Command;Ok(OriginalChildEditorCommandAdvance{progress:Self::paid(p),stamp:None})},
   Phase::Command=>{let p=command.bind(&mut self.command,child).map_err(Self::failure)?.unwrap_or_default();self.phase=Phase::Qualify;Ok(OriginalChildEditorCommandAdvance{progress:Self::paid(p),stamp:None})},
   Phase::Qualify=>{let identity=command.reference_identity().2;let request=ChildEditorRequest{identity,expected_reference_identity:qualified.reference,fields:read.current(&registration.identity).fields};let step=registration.qualify(read,&request,&mut self.cursor,child).map_err(|error|{let p=Self::paid(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes-Self::HEADER,..Default::default()});error.with_retained_progress(p)})?;Ok(OriginalChildEditorCommandAdvance{progress:Self::paid(self.cursor.last_receipt()),stamp:match step{ChildEditorSourceStep::Pending=>None,ChildEditorSourceStep::Ready(stamp)=>{self.issued=Some(stamp);Some(stamp)}}})},
   Phase::Closed=>unreachable!()
  }
 }
 pub fn take_authority_demand(&self)->Result<RetirementDemand,ValueError>{Self::nested(RetirementDemand{copy_bytes:2*std::mem::size_of::<OriginalChildEditorCommandAuthority>()+self.cursor.close_demand().copy_bytes,depth:1,..Default::default()})}
 pub fn take_authority<S:RetireOwned+Sync>(&mut self,custody:&super::ChildVectorSourceCustody<S>,read:&ChildEditorRead<'_,S>,g:RetainedCloneGrant)->Result<Option<(OriginalChildEditorCommandAuthority,RetainedCloneProgress)>,ValueError>{
  let d=self.take_authority_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None)}let fail=|message|refusal(message).with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:Self::HEADER,..Default::default()});
  if self.closing||self.phase!=Phase::Qualify{return Err(fail("Original child command authority is not ready"))}let stamp=self.issued.ok_or_else(||fail("Original child command qualification has not completed"))?;if custody.stamp()!=self.read.as_ref(){return Err(fail("Original child authority requires its exact qualified read custody"))}let child_source=custody.source().map_err(|error|error.with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:Self::HEADER,..Default::default()}))?;let current=read.member_metadata();
  if stamp.parent_identity()!=current.parent_identity||stamp.child_identity()!=current.child_identity||stamp.parent_revision()!=current.parent_revision||stamp.child_revision()!=current.child_revision||child_source.get()as*const S!=&*read.read as*const S{return Err(fail("Original child authority read or typed source changed"))}
  let mut child=None;let progress=child_source.bind(&mut child,Self::child(g)).map_err(Self::failure)?.unwrap_or_default();self.cursor.close_one(Self::child(g));let authority=OriginalChildEditorCommandAuthority{parent_original:self.read.unwrap().original,command_original:self.command_identity.unwrap(),child_original:child_source.reference_identity(),parent:self.parent.take(),command:self.command.take(),child,stamp:Some(stamp),closing:false};self.issued=None;self.command_identity=None;self.read=None;self.capability=None;self.phase=Phase::Closed;
  let mut progress=Self::paid(progress);progress.copied_bytes=d.copy_bytes;Ok(Some((authority,progress)))
 }
 pub fn begin_close(&mut self){if self.phase!=Phase::Closed{self.closing=true;self.cursor.cancel()}}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.phase==Phase::Closed{return Ok(Default::default())}let binding=if self.command.is_some(){&self.command}else{&self.parent};if binding.is_some(){Self::nested(RetainedCloneBinding::close_demand(binding,body.saturating_sub(Self::HEADER))?)}else{Self::nested(RetirementDemand{copy_bytes:std::mem::size_of::<OriginalChildEditorCommandCursor>(),depth:1,..Default::default()})}}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(refusal("Original child command closure has not begun"))}if self.phase==Phase::Closed{return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let binding=if self.command.is_some(){&mut self.command}else{&mut self.parent};if binding.is_some(){let p=RetainedCloneBinding::close_one(binding,Self::child(g)).map_err(Self::failure)?.progress();return Ok(RetainedCloneStep::Progress(Self::paid(p)))}self.cursor.close_one(Self::child(g));self.issued=None;self.command_identity=None;self.read=None;self.capability=None;self.phase=Phase::Closed;Ok(RetainedCloneStep::Complete(Self::paid(self.cursor.last_receipt())))}
 pub fn terminal_is_empty(&self)->bool{self.phase==Phase::Closed&&self.parent.is_none()&&self.command.is_none()&&self.cursor.terminal_is_empty()}
}
impl Drop for OriginalChildEditorCommandCursor{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Original child command bindings require funded closure")}}
struct CursorRetirement(Option<OriginalChildEditorCommandCursor>);
impl RetireOwned for OriginalChildEditorCommandCursor{fn retirement(self)->Box<dyn RetirementCursor>{Box::new(CursorRetirement(Some(self)))}fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<CursorRetirement>())}fn controlled_retirement_supported()->bool{true}}
impl RetirementCursor for CursorRetirement{fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.0.as_ref().map_or(Ok(Default::default()),|cursor|cursor.close_demand(body))}fn close_step(&mut self,g:RetainedCloneGrant)->RetirementStep{let Some(cursor)=self.0.as_mut()else{return RetirementStep::Complete};cursor.begin_close();match cursor.close_step(g){Err(error)=>RetirementStep::Failure(error),Ok(step)=>{let p=step.progress();if cursor.terminal_is_empty(){self.0=None}RetirementStep::Progress(p)}}}fn terminal_is_empty(&self)->bool{self.0.is_none()}fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(std::mem::size_of::<Self>())}}
impl<S> ChildEditorRegistration<S>{pub fn qualify_original<P:Sync,C:Sync>(&'static self,parent:RetainedCloneRef<'_,P>,command:RetainedCloneRef<'_,C>,qualified:&ChildVectorReadStamp,read:&ChildEditorRead<'_,S>,cursor:&mut OriginalChildEditorCommandCursor,g:RetainedCloneGrant)->Result<OriginalChildEditorCommandAdvance,ValueError>{cursor.advance(parent,command,qualified,read,self,g)}}

/// 🔐️ Publication retains the actual original parent, command and typed child issuer leases beside its private qualification.
pub struct OriginalChildEditorCommandAuthority{parent_original:(u64,usize,usize,usize),command_original:(u64,usize,usize,usize),child_original:(u64,usize,usize,usize),parent:Option<RetainedCloneBinding>,command:Option<RetainedCloneBinding>,child:Option<RetainedCloneBinding>,stamp:Option<ChildEditorStamp>,closing:bool}
impl OriginalChildEditorCommandAuthority{
 pub fn parent_source_identity(&self)->Option<(u64,usize,usize,usize)>{self.stamp().map(|_|self.parent_original)}
 pub fn command_source_identity(&self)->Option<(u64,usize,usize,usize)>{self.stamp().map(|_|self.command_original)}
 pub fn child_source_identity(&self)->Option<(u64,usize,usize,usize)>{self.stamp().map(|_|self.child_original)}
 pub fn stamp(&self)->Option<&ChildEditorStamp>{if self.closing{None}else{self.stamp.as_ref()}}
 pub fn begin_close(&mut self){self.closing=true}
 fn binding(&self)->&Option<RetainedCloneBinding>{if self.child.is_some(){&self.child}else if self.command.is_some(){&self.command}else{&self.parent}}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}let d=RetainedCloneBinding::close_demand(self.binding(),body.saturating_sub(2*std::mem::size_of::<Self>()))?;Ok(RetirementDemand{copy_bytes:d.copy_bytes+2*std::mem::size_of::<Self>(),depth:d.depth.max(1)+1,..d})}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(refusal("Original child authority closure has not begun"))}if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let header=2*std::mem::size_of::<Self>();let child=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-header,maximum_depth:g.maximum_depth-1,..g};let binding=if self.child.is_some(){&mut self.child}else if self.command.is_some(){&mut self.command}else{&mut self.parent};let mut p=if binding.is_some(){RetainedCloneBinding::close_one(binding,child).map_err(|error|{let mut p=error.retained_progress();p.copied_items=p.copied_items.max(1);p.copied_bytes+=header;error.with_retained_progress(p)})?.progress()}else{self.stamp=None;self.parent_original=(0,0,0,0);self.command_original=(0,0,0,0);self.child_original=(0,0,0,0);Default::default()};p.copied_items=p.copied_items.max(1);p.copied_bytes+=header;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn terminal_is_empty(&self)->bool{self.parent.is_none()&&self.command.is_none()&&self.child.is_none()&&self.stamp.is_none()}
}
impl Drop for OriginalChildEditorCommandAuthority{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Original child publication authority requires funded closure")}}
struct AuthorityRetirement(Option<OriginalChildEditorCommandAuthority>);
impl RetireOwned for OriginalChildEditorCommandAuthority{fn retirement(self)->Box<dyn RetirementCursor>{Box::new(AuthorityRetirement(Some(self)))}fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<AuthorityRetirement>())}fn controlled_retirement_supported()->bool{true}}
impl RetirementCursor for AuthorityRetirement{fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.0.as_ref().map_or(Ok(Default::default()),|authority|authority.close_demand(body))}fn close_step(&mut self,g:RetainedCloneGrant)->RetirementStep{let Some(authority)=self.0.as_mut()else{return RetirementStep::Complete};authority.begin_close();match authority.close_step(g){Err(error)=>RetirementStep::Failure(error),Ok(step)=>{let p=step.progress();if authority.terminal_is_empty(){self.0=None}RetirementStep::Progress(p)}}}fn terminal_is_empty(&self)->bool{self.0.is_none()}fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(std::mem::size_of::<Self>())}}

